   335|/****************************************************************************
   336| * 名称: run_timing
   337| *
   338| * 描述: 采样率 / 抖动测量模式（性能分析用）
   339| *
   340| * 【测量策略：双时基交叉标定】
   341| * 板子系统 tick 只有 10 ms（CONFIG_USEC_PER_TICK=10000），
   342| * 而 IMU 内部时间戳的 LSB 未在数据手册中明确对应本配置（实测反推
   343| * 约 1.6 ms）。两者单独都不足以测 μs 级抖动，但可以【交叉标定】：
   344| *
   345| *   1. 用系统 tick 测总耗时 T_total（5000 帧 ≈ 24 s，误差 <0.05%）
   346| *   2. 用 IMU 硬件时间戳测同期的总增量 Δstamp
   347| *   3. LSB = T_total / Δstamp   → 反标定出芯片时间戳的真实分辨率
   348| *   4. 用标定后的 LSB 分析每个间隔的分布 → 得到抖动
   349| *
   350| * 【为什么可信】
   351| * - 平均采样率由 tick 直接测得（不依赖任何假设）
   352| * - 抖动由芯片时间戳测得（记录的是实际采样时刻，不受调度/I2C 影响）
   353| * - LSB 由实测标定（不依赖手册推测）
   354| *
   355| * 【用法】nsh> aura_demo timing [帧数]     默认 5000 帧（约 24 秒）
   356| ****************************************************************************/
   357|#define TIMING_MAX_N      8000         /* 采样点上限（静态数组，无动态内存） */
   358|#define TIMING_WRAP_MASK  0xFFFFFFu    /* 24 位计数器回绕掩码 */
   359|
   360|static void run_timing(int n_frames)
   361|{
   362|  struct imu_frame_s f;
   363|  static uint32_t stamps[TIMING_MAX_N];   /* 静态分配，避免大栈占用 */
   364|  int    got = 0;
   365|  int    i;
   366|  struct timespec ts_start, ts_end;
   367|  double total_sec;
   368|
   369|  if (n_frames <= 0)          n_frames = 5000;
   370|  if (n_frames > TIMING_MAX_N) n_frames = TIMING_MAX_N;
   371|
   372|  printf("\n[TIMING] 采样率 / 抖动测量模式（双时基交叉标定）\n");
   373|  printf("[TIMING] 连续采集 %d 帧（约 %.1f 秒），请保持板子静止\n\n",
   374|         n_frames, n_frames * 4.8f / 1000.0f);
   375|
   376|  /* ---- 起点计时（系统 tick，10 ms 精度；长时段统计误差 <0.05%） ---- */
   377|  clock_gettime(CLOCK_MONOTONIC, &ts_start);
   378|
   379|  printf("[TIMING] 采集中");
   380|  for (i = 0; i < n_frames; i++)
   381|    {
   382|      if (imu_sample(&f) != 0)
   383|        {
   384|          usleep(1000);
   385|          continue;
   386|        }
   387|      stamps[got++] = f.hw_timestamp;
   388|
   389|      if ((i % 500) == 0)
   390|        {
   391|          printf(".");
   392|        }
   393|      usleep(5000);   /* 按 208Hz 节拍 */
   394|    }
   395|  clock_gettime(CLOCK_MONOTONIC, &ts_end);
   396|  printf(" 完成\n\n");
   397|
   398|  if (got < 20)
   399|    {
   400|      printf("[TIMING] 采样点不足（%d），无法统计。\n", got);
   401|      return;
   402|    }
   403|
   404|  /* ---- 总耗时（秒） ---- */
   405|  total_sec = (double)(ts_end.tv_sec - ts_start.tv_sec)
   406|              + (double)(ts_end.tv_nsec - ts_start.tv_nsec) / 1e9;
   407|  if (total_sec <= 0.0)
   408|    {
   409|      printf("[TIMING] 计时异常（总耗时 %.3f s），无法统计。\n", total_sec);
   410|      return;
   411|    }
   412|
   413|  /* ---- 时间戳总增量（处理 24 位回绕） ---- */
   414|  {
   415|    uint32_t first = stamps[0];
   416|    uint32_t last  = stamps[got - 1];
   417|    uint32_t total_span;
   418|    int      wraps = 0;
   419|
   420|    /* 统计回绕次数 */
   421|    for (i = 1; i < got; i++)
   422|      {
   423|        if (stamps[i] < stamps[i - 1])
   424|          {
   425|            wraps++;
   426|          }
   427|      }
   428|
   429|    total_span = (wraps > 0)
   430|                 ? (uint32_t)((uint64_t)wraps * (TIMING_WRAP_MASK + 1u)
   431|                              + (uint32_t)(last - first))
   432|                 : (uint32_t)(last - first);
   433|
   434|    if (total_span == 0)
   435|      {
   436|        printf("[TIMING] 时间戳未变化（总增量 0），芯片时间戳可能未工作。\n");
   437|        printf("         此时仅输出采样率结果。\n\n");
   438|      }
   439|
   440|    printf("============================================================\n");
   441|    printf("采样性能测量结果（双时基交叉标定）\n");
   442|    printf("============================================================\n");
   443|    printf("  采样点数              : %d\n", got);
   444|    printf("  总耗时（系统 tick）   : %.3f s\n", total_sec);
   445|    printf("  实际平均采样率        : %.2f Hz\n",
   446|           (double)(got - 1) / total_sec);
   447|    printf("  平均采样间隔          : %.1f μs\n",
   448|           total_sec * 1e6 / (double)(got - 1));
   449|    printf("  （标称 208 Hz → 4807.7 μs）\n");
   450|    printf("  采样率相对偏差        : %.3f %%\n",
   451|           (208.0 - (double)(got - 1) / total_sec) / 208.0 * 100.0);
   452|    printf("\n");
   453|
   454|    if (total_span > 0)
   455|      {
   456|        double lsb_us = total_sec * 1e6 / (double)total_span;
   457|        double sum = 0.0, sumsq = 0.0;
   458|        int    n = 0;
   459|        uint32_t prev = stamps[0];
