 * 名称: compute_features
 * 描述: 阶段三 —— 计算窗口特征
 *
 * 输出: x_peak        —— X 轴绝对峰值
 *       x_peak_signed —— X 轴带符号峰值（判断正负方向）
 *       y_mean        —— Y 轴「有效均值」（见下方说明）
 *       x_pos_ratio   —— X 轴正向采样占比
 *       y_peak        —— Y 轴绝对峰值
 *       gyro_mag_mean —— 三轴合成角速度均值
 *       gyro_mag_peak —— 三轴合成角速度【峰值】（用于运动量判定）
 *
 * 【关于 y_mean 的重要设计说明】
 * 直接用整个窗口的算术平均作为甩动判据存在固有缺陷：
 * 窗口 200ms（42 帧）而甩动平台约 300ms，当窗口落在平台边缘时，
 * 一半样本接近 0，会把均值稀释到阈值以下，导致漏检。
 * 因此此处计算的是「有效均值（修剪均值）」：先取窗口内幅值最大的
 * 前 50% 样本，再对其求带符号均值。这样只要窗口覆盖到动作主体，
 * 判据就不受边缘对齐影响，同时仍保持"均值 >150°/s"的语义
 * 与实验报告 3.3 节的表述一致。
 *
 * 【关于 gyro_mag_peak 的说明】
 * 运动量判定同样不能用均值：动作刚发生时窗口前半段仍是静止的，
 * 均值会被稀释到很低，导致真实动作被误判为"无运动"而丢弃
 * （PC 端实测：该缺陷使左右甩识别率降至 83%/72%）。
 * 改用峰值后，只要窗口内出现足够强度的运动就能通过。
 ****************************************************************************/
static void compute_features(float *x_peak, float *x_peak_signed,
                             float *y_mean, float *x_pos_ratio,
                             float *y_peak, float *gyro_mag_mean,
                             float *gyro_mag_peak,
                             int *sustain_frames,
                             float *accel_dev_peak,
                             float *accel_mag_min,
                             float *accel_mag_max)
{
  float xp = 0.0f, xps = 0.0f;
  float ypk = 0.0f;
  float magsum = 0.0f, magpk = 0.0f;
  int   x_pos_cnt = 0;
  int   sustain = 0;
  int   n = GESTURE_WIN_FRAMES;
  int   valid = 0;
  float gx, gy, gz;

  /* 为了算 Y 轴修剪均值，需要保存窗口内 Y 的绝对值与带符号值 */
  float yabs[GESTURE_WIN_FRAMES];
  float ysgn[GESTURE_WIN_FRAMES];

  for (int i = 0; i < n; i++)
    {
      if (ring_get((uint32_t)i, &gx, &gy, &gz, NULL) < 0)
        {
          break;
        }

      /* X 轴峰值 */
      if (fabsf(gx) > xp)
        {
          xp  = fabsf(gx);
          xps = gx;
        }

      /* Y 轴峰值 */
      if (fabsf(gy) > ypk)
        {
          ypk = fabsf(gy);
        }

      /* X 轴正向占比 */
      if (gx > 0.0f)
        {
          x_pos_cnt++;
        }

      /* 三轴合成模长：累加求均值 + 记录峰值 */
      {
        float mag = sqrtf(gx * gx + gy * gy + gz * gz);
        magsum += mag;
        if (mag > magpk)
          {
            magpk = mag;
          }
      }

      /* 记录 Y 供后续算修剪均值 */
      yabs[valid] = fabsf(gy);
      ysgn[valid] = gy;

      /* 统计「持续超阈值」帧数：|Y| 超过判定阈值的样本个数。
       * 用于区分「甩动平台」（持续）与「抬手脉冲」（瞬时）。 */
      if (fabsf(gy) > GESTURE_SWING_Y_MEAN)
        {
          sustain++;
        }

      valid++;
    }

  if (valid == 0)
    {
      *x_peak = *x_peak_signed = *y_mean = *x_pos_ratio = *y_peak = 0.0f;
      *gyro_mag_mean = *gyro_mag_peak = 0.0f;
      if (sustain_frames) *sustain_frames = 0;
      return;
    }

  *x_peak        = xp;
  *x_peak_signed = xps;
  *x_pos_ratio   = (float)x_pos_cnt / (float)valid;
  *y_peak        = ypk;
  *gyro_mag_mean = magsum / (float)valid;
  *gyro_mag_peak = magpk;
  if (sustain_frames) *sustain_frames = sustain;

  /* ---- Y 轴修剪均值：取幅值最大的前 50% 样本求带符号均值 ---- */
  {
    int keep = valid / 2;
    if (keep < 1)
      {
        keep = 1;", "exit_code": 0, "error": null}

