#include "aura_game.h"

#include <limits.h>
#include <string.h>

static aura_judgement_t empty_judgement(void)
{
  aura_judgement_t out;
  memset(&out, 0, sizeof(out));
  out.expected = AURA_GESTURE_NONE;
  return out;
}

static int32_t elapsed_from_note(const aura_game_t *game, uint32_t now_ms)
{
  uint32_t elapsed = now_ms - game->started_ms;
  uint32_t note_at = game->notes[game->next_note].at_ms;
  return (int32_t)(elapsed - note_at);
}

static aura_judgement_t commit(aura_game_t *game, aura_grade_t grade,
                               int32_t error_ms)
{
  aura_judgement_t out = empty_judgement();
  out.grade = grade;
  out.expected = game->notes[game->next_note].gesture;
  out.error_ms = error_ms;

  if (grade == AURA_GRADE_MISS) {
    game->miss++;
    game->combo = 0;
  } else {
    uint32_t base = grade == AURA_GRADE_PERFECT ? 1000u : 500u;
    uint32_t capped_combo;

    game->combo++;
    if (game->combo > game->max_combo) {
      game->max_combo = game->combo;
    }
    capped_combo = game->combo > 50u ? 50u : game->combo;
    out.score = base + (base * capped_combo) / 100u;
    game->score += out.score;
    if (grade == AURA_GRADE_PERFECT) {
      game->perfect++;
    } else {
      game->good++;
    }
  }

  game->next_note++;
  out.combo = game->combo;
  if (game->next_note >= game->note_count) {
    game->running = false;
  }
  return out;
}

bool aura_game_load(aura_game_t *game, const aura_note_t *notes,
                    size_t note_count)
{
  size_t i;
  if (game == NULL || notes == NULL || note_count == 0 ||
      note_count > AURA_MAX_NOTES) {
    return false;
  }

  for (i = 0; i < note_count; i++) {
    if (notes[i].gesture < AURA_GESTURE_UP ||
        notes[i].gesture > AURA_GESTURE_RIGHT ||
        (i > 0 && notes[i].at_ms <= notes[i - 1].at_ms)) {
      return false;
    }
  }

  memset(game, 0, sizeof(*game));
  memcpy(game->notes, notes, note_count * sizeof(notes[0]));
  game->note_count = (uint16_t)note_count;
  return true;
