════════ 3. aura_body_port.c 怎么用的 ════════
#include "aura_body_port.h"

#include <errno.h>

#ifdef CONFIG_AURA_SPACE_BODY_INTERACTION
#include <pthread.h>
#include <unistd.h>

#include "gesture_recognize.h"
#include "imu_source.h"

static pthread_t g_body_thread;
static pthread_mutex_t g_body_lock = PTHREAD_MUTEX_INITIALIZER;
static volatile bool g_body_running;
static bool g_body_pending;
static aura_body_event_t g_body_event;

static void *body_worker(void *argument)
{
  (void)argument;
  while (g_body_running) {
    struct imu_frame_s frame;
    struct gesture_event_s gesture;
    if (imu_source_read(&frame) == 0 &&
        gesture_feed(&frame, &gesture) == 0 &&
        gesture.type != GESTURE_NONE && gesture.confidence >= 0.70f) {
      pthread_mutex_lock(&g_body_lock);
      g_body_event.gesture = (aura_gesture_t)gesture.type;
      g_body_event.timestamp_ms = gesture.timestamp_us / 1000u;
      g_body_event.confidence = (uint8_t)(gesture.confidence * 100.0f);
      g_body_pending = true;
      pthread_mutex_unlock(&g_body_lock);
    }
    usleep(4800);
  }
  return NULL;
}
#endif

int aura_body_port_init(void)
{
#ifdef CONFIG_AURA_SPACE_BODY_INTERACTION
  int result = imu_source_init(CONFIG_AURA_IMU_DEVPATH);
  if (result < 0) return result;
  gesture_init();
  gesture_start_calibration();
  g_body_pending = false;
  g_body_running = true;
  result = pthread_create(&g_body_thread, NULL, body_worker, NULL);
  if (result != 0) {
    g_body_running = false;
    imu_source_deinit();
    return -result;
  }
  return 0;
#else
  return -ENODEV;
#endif
}


