════════ 它的实现（是否走 /dev/lsm6dsl0）════════
int imu_source_init(const char *devpath)
{
  if (devpath == NULL)
    {
      devpath = IMU_DEFAULT_DEVPATH;
    }

  g_sensor_fd = open(devpath, O_RDONLY);
  if (g_sensor_fd < 0)
    {
      printf("[IMU] 打开 %s 失败: %d\n", devpath, errno);
      printf("      排查: 确认 CONFIG_SENSORS_LSM6DSL=y 且板级已注册该设备。\n");
      printf("      可执行 'ls /dev' 查看是否存在 lsm6dsl0 节点。\n");
      g_state = 2;
      return -errno;
    }

  /* 启动传感器数据流 */
  if (ioctl(g_sensor_fd, SNIOC_START, 0) < 0)
    {
      printf("[IMU] SNIOC_START 失败: %d\n", errno);
      /* 部分实现下 START 失败不致命，继续尝试读取 */
    }

  g_state = 1;
  printf("[IMU] 初始化成功: %s\n", devpath);
  return 0;
}

